ject single expert with weight=1.0\\n        - routing_weights: [N] tensor, blend N experts\\n        \\\"\\\"\\\"\\n        self._save_frozen_weights()\\n\\n        if expert_name is not None:\\n            params = self.experts[expert_name]\\n            for module_path, lora in params.items():\\n                A = lora[\\\"lora_A\\\"]  # [rank, in_features]\\n                B = lora[\\\"lora_B\\\"]  # [out_features, rank]\\n                delta = self.scaling * (B @ A)\\n                mod = _get_submodule(self.model, module_path)\\n                mod.weight.data.add_(delta.to(mod.weight.dtype))\\n        elif routing_weights is not None:\\n            expert_names = list(self.experts.keys())\\n            ref = self.experts[expert_names[0]]\\n            for module_path in ref:\\n                merged_A = torch.zeros_like(ref[module_path][\\\"lora_A\\\"])\\n                merged_B = torch.zeros_like(ref[module_path][\\\"lora_B\\\"])\\n                for i, en in enumerate(expert_names):\\n                    merged_A += routing_weights[i] * self.experts[en][module_path][\\\"lora_A\\\"]\\n                    merged_B += routing_weights[i] * self.experts[en][module_path][\\\"lora_B\\\"]\\n                delta = self.scaling * (merged_B @ merged_A)\\n                mod = _get_submodule(self.model, module_path)\\n                mod.weight.data.add_(delta.to(mod.weight.dtype))\\n\\n    def restore(self):\\n        \\\"\\\"\\\"Restore frozen weights.\\\"\\\"\\\"\\n        for module_path, frozen_w in self._frozen_weights.items():\\n            mod = _get_submodule(self.model, module_path)\\n            mod.weight.data.copy_(frozen_w)\\n\\n\\n# ---------------------------------------------------------------------------\\n# PAR Router (lightweight)\\n# ---------------------------------------------------------------------------\\n\\nclass PARRouterLite:\\n    \\\"\\\"\\\"Simplified PAR router for eval: hooks layer 6, runs classifier.\\\"\\\"\\\"\\n\\n    def _