{"type":"assistant","message":{"model":"claude-opus-4-6","id":"msg_0143K8sgXiaNXpr8hEz8Syrj","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01S7RvCA5TLDNSYJKdBs2pRF","name":"mcp__agent-ml-research__ssh_execute","input":{"server":"westd-34142","command":"cat > /root/meta_brain_lora_routing/phase0/collect_activations_real_env.py << 'SCRIPT'\n\"\"\"\nCollect PaliGemma layer-6 activations from REAL LIBERO-Plus environments.\n\nUnlike v3 (synthetic perturbations on clean images), this script:\n1. Loads actual LIBERO-Plus perturbation environments (background_textures, \n   camera_viewpoints, light_conditions, sensor_noise, objects_layout, robot_initial_states)\n2. Resets envs, steps to get real perturbed observations\n3. Runs pi0 model forward pass\n4. Captures layer-6 first-token activations\n\nOutput: /root/autodl-tmp/activations_real_env/activations.pt\n\"\"\"\n\nimport os\nos.environ[\"JAXTYPING_DISABLE\"] = \"1\"\nos.environ[\"MUJOCO_GL\"] = \"egl\"\n\nimport argparse\nimport collections\nimport json\nimport logging\nimport random\nimport sys\nimport time\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\n\nsys.path.insert(0, \"/root/meta_brain_lora_routing/phase1\")\nsys.path.insert(0, \"/root/meta_brain_lora_routing\")\nsys.path.insert(0, \"/root/openpi/src\")\nsys.path.insert(0, \"/root/openpi\")\n\nlogging.basicConfig(level=logging.INFO, format=\"%(asctime)s %(levelname)s %(message)s\")\nlog = logging.getLogger(__name__)\n\nPERTURBATION_TO_3CLASS = {\n    \"camera_viewpoints\": \"visual\",\n    \"light_conditions\": \"visual\",\n    \"background_textures\": \"visual\",\n    \"sensor_noise\": \"visual\",\n    \"objects_layout\": \"spatial\",\n    \"robot_initial_states\": \"physical\",\n}\n\nCLASS_TO_IDX = {\"visual\": 0, \"spatial\": 1, \"physical\": 2}\n\n\nclass Layer6Collector:\n    def __init__(self, model):\n        self.model = model\n        self._hook = None\n        self._activation = None\n\n    def register(self):\n        module_path = \"paligemma_with_expert.paligemma.model.language_model.layers.6\"\n        m = self.model\n        for p in module_path.split(\".\"):\n            m = getattr(m, p)\n        self._hook = m.register_forward_hook(self._hook_fn)\n        log.info(\"Hooked PaliGemma layer 6 (id=%d)\", id(m))\n\n    def _hook_fn(self, _module, _input, output):\n        if isinstance(output, tuple):\n            h = output[0]\n        else:\n            h = output\n        self._activation = h[:, 0].detach().float().cpu()\n\n    def get(self):\n        act = self._activation\n        self._activation = None\n        return act\n\n    def remove(self):\n        if self._hook:\n            self._hook.remove()\n            self._hook = None\n\n\ndef collect_from_perturbation(policy, collector, task_suite, perturbation_type,\n                              num_tasks, steps_per_task, seed):\n    \"\"\"Collect activations from one perturbation type.\"\"\"\n    from evaluate_libero_plus import (\n        get_tasks_by_perturbation, create_libero_env, obs_to_model_input,\n        NUM_STEPS_WAIT, LIBERO_DUMMY_ACTION,\n    )\n\n    task_ids = get_tasks_by_perturbation(task_suite, perturbation_type)\n    if not task_ids:\n        log.warning(\"No tasks for %s/%s\", task_suite, perturbation_type)\n        return [], []\n\n    rng = random.Random(seed)\n    selected_tasks = rng.sample(task_ids, min(num_tasks, len(task_ids)))\n    \n    activations = []\n    metadata = []\n    \n    for task_idx, task_id in enumerate(selected_tasks):\n        try:\n            env, task_desc, init_states, sel_idx, suite_key = create_libero_env(\n                task_suite, perturbation_type, seed + task_idx\n            )\n        except Exception as e:\n            log.warning(\"Failed to create env for task %s: %s\", task_id, e)\n            continue\n\n        try:\n            trial_idx = rng.randint(0, len(init_states) - 1)\n            obs = env.set_init_state(init_states[trial_idx])\n            for _ in range(NUM_STEPS_WAIT):\n                obs, _, _, _ = env.step(LIBERO_DUMMY_ACTION)\n\n            for step in range(steps_per_task):\n                obs_dict = obs_to_model_input(obs, task_desc)\n                _ = policy.infer(obs_dict)\n                act = collector.get()\n                \n                if act is not None:\n                    activations.append(act.squeeze(0))\n                    metadata.append({\n                        \"perturbation_type\": perturbation_type,\n                        \"class_3\": PERTURBATION_TO_3CLASS[perturbation_type],\n                        \"task_suite\": task_suite,\n                        \"task_id\": str(sel_idx),\n                        \"step\": step,\n                    })\n                \n                obs, _, done, _ = env.step(LIBERO_DUMMY_ACTION)\n                if done:\n                    break\n        except Exception as e:\n            log.warning(\"Error during collection from %s task %d: %s\", \n                       perturbation_type, task_idx, e)\n        finally:\n            env.close()\n        \n        if (task_idx + 1) % 10 == 0:\n            log.info(\"  [%s] %d/%d tasks done, %d activations collected\",\n                    perturbation_type, task_idx + 1, len(selected_tasks), len(activations))\n\n    return activations, metadata\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--device\", default=\"cuda:2\")\n    parser.add_argument(\"--output_dir\", default=\"/root/autodl-tmp/activations_real_env\")\n    parser.add_argument(\"--task_suite\", default=\"libero_spatial\")\n    parser.add_argument(\"--num_tasks_per_perturbation\", type=int, default=50)\n    parser.add_argument(\"--steps_per_task\", type=int, default=10)\n    parser.add_argument(\"--seed\", type=int, default=42)\n    parser.add_argument(\"--checkpoint\", default=\"/root/autodl-tmp/checkpoints/pi0_libero_openpi\")\n    args = parser.parse_args()\n\n    device = args.device\n    os.makedirs(args.output_dir, exist_ok=True)\n\n    log.info(\"Loading policy on %s...\", device)\n    from openpi_metabrain_policy import OpenPIMetaBrainPolicy\n    policy_wrapper = OpenPIMetaBrainPolicy.from_checkpoint(\n        checkpoint_path=args.checkpoint,\n        routing_mode='none',\n        device=device,\n        use_delta_actions=True,\n    )\n    policy_wrapper._diag_max = 0\n\n    collector = Layer6Collector(policy_wrapper.model)\n    collector.register()\n\n    # Verify activation norm\n    log.info(\"Verifying hook with dummy forward pass...\")\n    from evaluate_libero_plus import obs_to_model_input\n    dummy_obs = {\n        \"agentview_image\": np.zeros((224, 224, 3), dtype=np.uint8),\n        \"robot0_eye_in_hand_image\": np.zeros((224, 224, 3), dtype=np.uint8),\n        \"robot0_eef_pos\": np.zeros(3, dtype=np.float32),\n        \"robot0_eef_quat\": np.array([0, 0, 0, 1], dtype=np.float32),\n        \"robot0_gripper_qpos\": np.zeros(2, dtype=np.float32),\n    }\n    dummy_dict = obs_to_model_input(dummy_obs, \"test task\")\n    _ = policy_wrapper.infer(dummy_dict)\n    test_act = collector.get()\n    if test_act is not None:\n        norm = test_act.norm().item()\n        log.info(\"Verification: activation dim=%d, norm=%.1f\", test_act.shape[-1], norm)\n        if norm > 10000:\n            log.error(\"ACTIVATION NORM ABNORMAL (%.1f >> 250). Hook may be wrong!\", norm)\n            return\n    else:\n        log.error(\"Hook returned None! Check hook registration.\")\n        return\n\n    # Collect from each perturbation type\n    perturbation_types = [\n        \"background_textures\", \"camera_viewpoints\", \"light_conditions\", \"sensor_noise\",\n        \"objects_layout\", \"robot_initial_states\",\n    ]\n    \n    # Balance classes: visual has 4 sub-types, spatial 1, physical 1\n    # Collect fewer per visual sub-type to balance\n    samples_config = {\n        \"background_textures\": args.num_tasks_per_perturbation,\n        \"camera_viewpoints\": args.num_tasks_per_perturbation,\n        \"light_conditions\": args.num_tasks_per_perturbation,\n        \"sensor_noise\": args.num_tasks_per_perturbation,\n        \"objects_layout\": args.num_tasks_per_perturbation * 2,\n        \"robot_initial_states\": args.num_tasks_per_perturbation * 2,\n    }\n\n    all_activations = []\n    all_metadata = []\n\n    for ptype in perturbation_types:\n        n_tasks = samples_config[ptype]\n        log.info(\"Collecting from %s (%d tasks × %d steps)...\", ptype, n_tasks, args.steps_per_task)\n        t0 = time.time()\n        \n        acts, meta = collect_from_perturbation(\n            policy_wrapper, collector, args.task_suite, ptype,\n            n_tasks, args.steps_per_task, args.seed\n        )\n        \n        elapsed = time.time() - t0\n        log.info(\"  %s: %d activations in %.1fs\", ptype, len(acts), elapsed)\n        all_activations.extend(acts)\n        all_metadata.extend(meta)\n\n    # Save results\n    if not all_activations:\n        log.error(\"No activations collected!\")\n        return\n\n    X = torch.stack(all_activations)\n    labels_3class = torch.tensor([CLASS_TO_IDX[m[\"class_3\"]] for m in all_metadata])\n    \n    # Summary\n    class_counts = collections.Counter(labels_3class.numpy().tolist())\n    log.info(\"Total samples: %d\", len(X))\n    log.info(\"Class distribution: visual=%d, spatial=%d, physical=%d\",\n             class_counts.get(0, 0), class_counts.get(1, 0), class_counts.get(2, 0))\n    log.info(\"Activation shape: %s, mean norm: %.1f\", X.shape, X.norm(dim=-1).mean().item())\n\n    save_path = Path(args.output_dir) / \"activations.pt\"\n    torch.save({\n        \"activations\": X,\n        \"labels_3class\": labels_3class,\n        \"metadata\": all_metadata,\n        \"config\": {\n            \"task_suite\": args.task_suite,\n            \"num_tasks_per_perturbation\": args.num_tasks_per_perturbation,\n            \"steps_per_task\": args.steps_per_task,\n            \"seed\": args.seed,\n            \"device\": device,\n            \"hook_path\": \"paligemma_with_expert.paligemma.model.language_model.layers.6\",\n            \"pooling\": \"first_token\",\n        }\n    }, save_path)\n    log.info(\"Saved to %s\", save_path)\n\n    policy_wrapper.cleanup()\n\n\nif __name__ == \"__main__\":\n    main()\nSCRIPT\necho \"Script written successfully\"","account":"root"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":2371,"cache_read_input_tokens":54030,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":2371},"output_tokens":8,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"cbea082d-eac9-4f77-9b36-638b6bf0cf28","uuid":"7bce2d01-bf72-464d-9013-3930e131ca0f"}
