{"type":"assistant","message":{"model":"claude-opus-4-6","id":"msg_01TUZV13HpNiwaDkTaRJDdo5","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01JvCd2cSj6mbaDY3uYdwCqg","name":"mcp__agent-ml-research__ssh_execute","input":{"server":"westd-34142","command":"cat > /root/meta_brain_lora_routing/phase0/collect_activations_real_env_multilayer.py << 'SCRIPT'\n\"\"\"\nCollect multi-layer PaliGemma activations from REAL LIBERO-Plus environments.\nHooks layers [2, 4, 6, 8, 10, 12, 14, 16] and captures first-token from each.\nOutput dim: 8 * 2048 = 16384 (same as Phase 0 paligemma_only + first pooling).\n\"\"\"\n\nimport os\nos.environ[\"JAXTYPING_DISABLE\"] = \"1\"\nos.environ[\"MUJOCO_GL\"] = \"egl\"\n\nimport argparse\nimport collections\nimport json\nimport logging\nimport random\nimport sys\nimport time\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\n\nsys.path.insert(0, \"/root/meta_brain_lora_routing/phase1\")\nsys.path.insert(0, \"/root/meta_brain_lora_routing\")\nsys.path.insert(0, \"/root/openpi/src\")\nsys.path.insert(0, \"/root/openpi\")\n\nlogging.basicConfig(level=logging.INFO, format=\"%(asctime)s %(levelname)s %(message)s\")\nlog = logging.getLogger(__name__)\n\nPERTURBATION_TO_3CLASS = {\n    \"camera_viewpoints\": \"visual\",\n    \"light_conditions\": \"visual\",\n    \"background_textures\": \"visual\",\n    \"sensor_noise\": \"visual\",\n    \"objects_layout\": \"spatial\",\n    \"robot_initial_states\": \"physical\",\n}\nCLASS_TO_IDX = {\"visual\": 0, \"spatial\": 1, \"physical\": 2}\nPALIGEMMA_LAYERS = [2, 4, 6, 8, 10, 12, 14, 16]\n\n\nclass MultiLayerCollector:\n    def __init__(self, model):\n        self.model = model\n        self._hooks = []\n        self._activations = {}\n\n    def register(self):\n        layers_module = self.model.paligemma_with_expert.paligemma.model.language_model.layers\n        n_layers = len(layers_module)\n        log.info(\"Model has %d layers\", n_layers)\n        \n        for i in PALIGEMMA_LAYERS:\n            if i >= n_layers:\n                log.warning(\"Layer %d out of range (max=%d), skipping\", i, n_layers-1)\n                continue\n            layer = layers_module[i]\n            hook = layer.register_forward_hook(self._make_hook(i))\n            self._hooks.append(hook)\n        log.info(\"Hooked %d layers: %s\", len(self._hooks), \n                [i for i in PALIGEMMA_LAYERS if i < n_layers])\n\n    def _make_hook(self, layer_idx):\n        def hook_fn(_module, _input, output):\n            h = output[0] if isinstance(output, tuple) else output\n            self._activations[layer_idx] = h[:, 0].detach().float().cpu()\n        return hook_fn\n\n    def get(self):\n        if not self._activations:\n            return None\n        parts = []\n        for i in PALIGEMMA_LAYERS:\n            if i in self._activations:\n                parts.append(self._activations[i].squeeze(0))\n        self._activations.clear()\n        if not parts:\n            return None\n        return torch.cat(parts, dim=-1)\n\n    def remove(self):\n        for h in self._hooks:\n            h.remove()\n        self._hooks.clear()\n\n\ndef collect_from_perturbation(policy, collector, task_suite, perturbation_type,\n                              num_envs, steps_per_env, seed):\n    from evaluate_libero_plus import (\n        get_tasks_by_perturbation, obs_to_model_input,\n        NUM_STEPS_WAIT, LIBERO_DUMMY_ACTION, IMAGE_SIZE,\n        _extract_base_task_name,\n    )\n    from libero.libero import get_libero_path\n    from libero.libero.envs import OffScreenRenderEnv\n\n    task_ids = get_tasks_by_perturbation(task_suite, perturbation_type)\n    if not task_ids:\n        return [], []\n\n    rng = random.Random(seed)\n    bddl_root = Path(get_libero_path(\"bddl_files\"))\n    init_root = Path(get_libero_path(\"init_states\"))\n\n    activations = []\n    metadata = []\n    env_count = 0\n    fail_count = 0\n\n    shuffled_tasks = list(task_ids)\n    rng.shuffle(shuffled_tasks)\n\n    for task_id in shuffled_tasks:\n        if env_count >= num_envs:\n            break\n        if not isinstance(task_id, str):\n            continue\n\n        task_name = task_id\n        base_name = _extract_base_task_name(task_name)\n        task_description = base_name.replace(\"_\", \" \")\n\n        has_view_encoding = \"_view_\" in task_name and \"_initstate_\" in task_name\n        if has_view_encoding:\n            bddl_path = str(bddl_root / task_suite / f\"{task_name}.bddl\")\n            base_bddl = bddl_root / task_suite / f\"{base_name}.bddl\"\n            if not base_bddl.exists():\n                continue\n        else:\n            bddl_path = str(bddl_root / task_suite / f\"{task_name}.bddl\")\n            if not Path(bddl_path).exists():\n                continue\n\n        try:\n            env = OffScreenRenderEnv(\n                bddl_file_name=bddl_path,\n                camera_heights=IMAGE_SIZE,\n                camera_widths=IMAGE_SIZE,\n            )\n            env.seed(seed + env_count)\n        except Exception:\n            fail_count += 1\n            continue\n\n        try:\n            use_reset = has_view_encoding\n            if not use_reset:\n                init_path = init_root / task_suite / f\"{base_name}.pruned_init\"\n                if init_path.exists():\n                    init_states = torch.load(str(init_path), weights_only=False)\n                    trial_idx = rng.randint(0, len(init_states) - 1)\n                    try:\n                        obs = env.set_init_state(init_states[trial_idx])\n                    except (ValueError, RuntimeError):\n                        use_reset = True\n                else:\n                    use_reset = True\n\n            if use_reset:\n                obs = env.reset()\n\n            for _ in range(NUM_STEPS_WAIT):\n                obs, _, _, _ = env.step(LIBERO_DUMMY_ACTION)\n\n            for step in range(steps_per_env):\n                obs_dict = obs_to_model_input(obs, task_description)\n                _ = policy.infer(obs_dict)\n                act = collector.get()\n\n                if act is not None:\n                    activations.append(act)\n                    metadata.append({\n                        \"perturbation_type\": perturbation_type,\n                        \"class_3\": PERTURBATION_TO_3CLASS[perturbation_type],\n                        \"task_suite\": task_suite,\n                        \"task_name\": task_name[:80],\n                        \"step\": step,\n                    })\n\n                obs, _, done, _ = env.step(LIBERO_DUMMY_ACTION)\n                if done:\n                    break\n\n            env_count += 1\n        except Exception:\n            fail_count += 1\n        finally:\n            env.close()\n\n        if env_count % 10 == 0 and env_count > 0:\n            log.info(\"  [%s] %d/%d envs, %d acts, %d fails\",\n                    perturbation_type, env_count, num_envs, len(activations), fail_count)\n\n    log.info(\"  [%s] Final: %d envs, %d activations, %d failures\",\n            perturbation_type, env_count, len(activations), fail_count)\n    return activations, metadata\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--device\", default=\"cuda:0\")\n    parser.add_argument(\"--output_dir\", default=\"/root/autodl-tmp/activations_real_env_multilayer\")\n    parser.add_argument(\"--task_suite\", default=\"libero_spatial\")\n    parser.add_argument(\"--num_envs_per_perturbation\", type=int, default=40)\n    parser.add_argument(\"--steps_per_env\", type=int, default=8)\n    parser.add_argument(\"--seed\", type=int, default=42)\n    parser.add_argument(\"--checkpoint\", default=\"/root/autodl-tmp/checkpoints/pi0_libero_openpi\")\n    args = parser.parse_args()\n\n    device = args.device\n    os.makedirs(args.output_dir, exist_ok=True)\n\n    log.info(\"Loading policy on %s...\", device)\n    from openpi_metabrain_policy import OpenPIMetaBrainPolicy\n    policy_wrapper = OpenPIMetaBrainPolicy.from_checkpoint(\n        checkpoint_path=args.checkpoint,\n        routing_mode='none',\n        device=device,\n        use_delta_actions=True,\n    )\n    policy_wrapper._diag_max = 0\n\n    collector = MultiLayerCollector(policy_wrapper.model)\n    collector.register()\n\n    # Sanity check\n    from evaluate_libero_plus import obs_to_model_input\n    dummy_obs = {\n        \"agentview_image\": np.zeros((224, 224, 3), dtype=np.uint8),\n        \"robot0_eye_in_hand_image\": np.zeros((224, 224, 3), dtype=np.uint8),\n        \"robot0_eef_pos\": np.zeros(3, dtype=np.float32),\n        \"robot0_eef_quat\": np.array([0, 0, 0, 1], dtype=np.float32),\n        \"robot0_gripper_qpos\": np.zeros(2, dtype=np.float32),\n    }\n    _ = policy_wrapper.infer(obs_to_model_input(dummy_obs, \"test\"))\n    test_act = collector.get()\n    if test_act is None:\n        log.error(\"Hook returned None!\")\n        return\n    log.info(\"Hook OK: dim=%d (expected %d)\", test_act.shape[-1], len(PALIGEMMA_LAYERS) * 2048)\n\n    perturbation_types = [\n        \"background_textures\", \"camera_viewpoints\", \"light_conditions\", \"sensor_noise\",\n        \"objects_layout\", \"robot_initial_states\",\n    ]\n    visual_envs = args.num_envs_per_perturbation\n    other_envs = args.num_envs_per_perturbation * 3\n    samples_config = {\n        \"background_textures\": visual_envs,\n        \"camera_viewpoints\": visual_envs,\n        \"light_conditions\": visual_envs,\n        \"sensor_noise\": visual_envs,\n        \"objects_layout\": other_envs,\n        \"robot_initial_states\": other_envs,\n    }\n\n    all_activations = []\n    all_metadata = []\n\n    for ptype in perturbation_types:\n        n_envs = samples_config[ptype]\n        log.info(\"Collecting from %s (%d envs × %d steps)...\", ptype, n_envs, args.steps_per_env)\n        t0 = time.time()\n        acts, meta = collect_from_perturbation(\n            policy_wrapper, collector, args.task_suite, ptype,\n            n_envs, args.steps_per_env, args.seed\n        )\n        log.info(\"  %s: %d activations in %.1fs\", ptype, len(acts), time.time() - t0)\n        all_activations.extend(acts)\n        all_metadata.extend(meta)\n\n    if not all_activations:\n        log.error(\"No activations collected!\")\n        return\n\n    X = torch.stack(all_activations)\n    labels_3class = torch.tensor([CLASS_TO_IDX[m[\"class_3\"]] for m in all_metadata])\n\n    class_counts = collections.Counter(labels_3class.numpy().tolist())\n    log.info(\"=\" * 60)\n    log.info(\"COLLECTION COMPLETE\")\n    log.info(\"Total: %d, Shape: %s\", len(X), X.shape)\n    log.info(\"Classes: visual=%d, spatial=%d, physical=%d\",\n             class_counts.get(0, 0), class_counts.get(1, 0), class_counts.get(2, 0))\n    log.info(\"=\" * 60)\n\n    save_path = Path(args.output_dir) / \"activations.pt\"\n    torch.save({\n        \"activations\": X,\n        \"labels_3class\": labels_3class,\n        \"metadata\": all_metadata,\n        \"config\": {\n            \"task_suite\": args.task_suite,\n            \"layers\": PALIGEMMA_LAYERS,\n            \"pooling\": \"first_token\",\n            \"layer_template\": \"paligemma_with_expert.paligemma.model.language_model.layers.{i}\",\n        }\n    }, save_path)\n    log.info(\"Saved to %s\", save_path)\n    policy_wrapper.cleanup()\n\n\nif __name__ == \"__main__\":\n    main()\nSCRIPT\necho \"Multi-layer collection script written\"","account":"root"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":1790,"cache_read_input_tokens":160086,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":1790},"output_tokens":8,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"cbea082d