{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_014eyT6vQfVKvirMTjTZ8eeQ","type":"tool_result","content":"{\"result\":\"{\\\"success\\\": true, \\\"data\\\": {\\\"stdout\\\": \\\"\\\\\\\"\\\\\\\"\\\\\\\"\\\\nTrain PAR Router on real LIBERO-Plus activations (3-class: visual/spatial/physical).\\\\n\\\\nInput: activations.pt from collect_activations_real_env.py\\\\nOutput: PAR router checkpoint compatible with phase1/par_router.py\\\\n\\\\n5-fold stratified cross-validation, reports macro F1.\\\\n\\\\\\\"\\\\\\\"\\\\\\\"\\\\n\\\\nimport argparse\\\\nimport json\\\\nimport logging\\\\nimport os\\\\nfrom pathlib import Path\\\\n\\\\nimport numpy as np\\\\nimport torch\\\\nimport torch.nn as nn\\\\nimport torch.optim as optim\\\\nfrom sklearn.metrics import f1_score, classification_report\\\\nfrom sklearn.model_selection import StratifiedKFold\\\\nfrom torch.utils.data import DataLoader, TensorDataset, Subset\\\\n\\\\nlogging.basicConfig(level=logging.INFO, format=\\\\\\\"%(asctime)s %(levelname)s %(message)s\\\\\\\")\\\\nlog = logging.getLogger(__name__)\\\\n\\\\nCLASS_NAMES = [\\\\\\\"visual\\\\\\\", \\\\\\\"spatial\\\\\\\", \\\\\\\"physical\\\\\\\"]\\\\n\\\\n\\\\nclass PARRouterModel(nn.Module):\\\\n    def __init__(self, input_dim=2048, hidden_dim=256, num_classes=3, dropout=0.1):\\\\n        super().__init__()\\\\n        self.net = nn.Sequential(\\\\n            nn.Linear(input_dim, hidden_dim),\\\\n            nn.ReLU(),\\\\n            nn.Dropout(dropout),\\\\n            nn.Linear(hidden_dim, num_classes),\\\\n        )\\\\n\\\\n    def forward(self, x):\\\\n        return self.net(x)\\\\n\\\\n\\\\ndef train_one_fold(X_train, y_train, X_val, y_val, input_dim, num_classes,\\\\n                   lr, epochs, device, hidden_dim=256, dropout=0.1):\\\\n    model = PARRouterModel(input_dim, hidden_dim, num_classes, dropout).to(device)\\\\n    optimizer = optim.AdamW(model.parameters(), lr=lr, weight_decay=1e-4)\\\\n    scheduler = optim.lr_scheduler.CosineAnnealingLR(optimizer, T_max=epochs)\\\\n    criterion = nn.CrossEntropyLoss()\\\\n\\\\n    train_ds = TensorDataset(X_train.to(device), y_train.to(device))\\\\n    train_loader = DataLoader(train_ds, batch_size=128, shuffle=True)\\\\n\\\\n    best_f1 = 0.0\\\\n    best_state = None\\\\n\\\\n    for epoch in range(epochs):\\\\n        model.train()\\\\n        for xb, yb in train_loader:\\\\n            optimizer.zero_grad()\\\\n            loss = criterion(model(xb), yb)\\\\n            loss.backward()\\\\n            optimizer.step()\\\\n        scheduler.step()\\\\n\\\\n        model.eval()\\\\n        with torch.no_grad():\\\\n            logits = model(X_val.to(device))\\\\n            preds = logits.argmax(dim=-1).cpu().numpy()\\\\n            y_true = y_val.numpy()\\\\n            f1 = f1_score(y_true, preds, average=\\\\\\\"macro\\\\\\\")\\\\n\\\\n        if f1 > best_f1:\\\\n            best_f1 = f1\\\\n            best_state = {k: v.cpu().clone() for k, v in model.state_dict().items()}\\\\n\\\\n    return best_f1, best_state\\\\n\\\\n\\\\ndef cross_validate(X, y, input_dim, num_classes, lr, epochs, device,\\\\n                   n_folds=5, hidden_dim=256, dropout=0.1):\\\\n    skf = StratifiedKFold(n_splits=n_folds, shuffle=True, random_state=42)\\\\n    fold_f1s = []\\\\n    best_overall_f1 = 0.0\\\\n    best_overall_state = None\\\\n\\\\n    for fold, (train_idx, val_idx) in enumerate(skf.split(X, y)):\\\\n        X_train, X_val = X[train_idx], X[val_idx]\\\\n        y_train, y_val = y[train_idx], y[val_idx]\\\\n\\\\n        f1, state = train_one_fold(\\\\n            X_train, y_train, X_val, y_val,\\\\n            input_dim, num_classes, lr, epochs, device, hidden_dim, dropout\\\\n        )\\\\n        fold_f1s.append(f1)\\\\n        log.info(\\\\\\\"  Fold %d: F1=%.4f\\\\\\\", fold + 1, f1)\\\\n\\\\n        if f1 > best_overall_f1:\\\\n            best_overall_f1 = f1\\\\n            best_overall_state = state\\\\n\\\\n    mean_f1 = np.mean(fold_f1s)\\\\n    std_f1 = np.std(fold_f1s)\\\\n    log.info(\\\\\\\"  CV: F1=%.4f +/- %.4f\\\\\\\", mean_f1, std_f1)\\\\n    return mean_f1, std_f1, fold_f1s, best_overall_state\\\\n\\\\n\\\\ndef main():\\\\n    parser = argparse.ArgumentParser()\\\\n    parser.add_argument(\\\\\\\"--data_path\\\\\\\", default=\\\\\\\"/root/autodl-tmp/activations_real_env/activations.pt\\\\\\\")\\\\n    parser.add_argument(\\\\\\\"--output_dir\\\\\\\", default=\\\\\\\"/root/autodl-tmp/checkpoints/par_router_real_env\\\\\\\")\\\\n    parser.add_argument(\\\\\\\"--device\\\\\\\", default=\\\\\\\"cuda:2\\\\\\\")\\\\n    parser.add_argument(\\\\\\\"--lr\\\\\\\", type=float, default=1e-3)\\\\n    parser.add_argument(\\\\\\\"--epochs\\\\\\\", type=int, default=100)\\\\n    parser.add_argument(\\\\\\\"--hidden_dim\\\\\\\", type=int, default=256)\\\\n    parser.add_argument(\\\\\\\"--dropout\\\\\\\", type=float, default=0.1)\\\\n    parser.add_argument(\\\\\\\"--normalize\\\\\\\", action=\\\\\\\"store_true\\\\\\\")\\\\n    args = parser.parse_args()\\\\n\\\\n    device = args.device\\\\n    os.makedirs(args.output_dir, exist_ok=True)\\\\n\\\\n    log.info(\\\\\\\"Loading activations from %s\\\\\\\", args.data_path)\\\\n    data = torch.load(args.data_path, weights_only=False)\\\\n    X = data[\\\\\\\"activations\\\\\\\"]\\\\n    y = data[\\\\\\\"labels_3class\\\\\\\"]\\\\n\\\\n    log.info(\\\\\\\"Data: X=%s, y=%s\\\\\\\", X.shape, y.shape)\\\\n    log.info(\\\\\\\"Class counts: %s\\\\\\\", {CLASS_NAMES[i]: (y == i).sum().item() for i in range(3)})\\\\n    log.info(\\\\\\\"Mean activation norm: %.1f\\\\\\\", X.norm(dim=-1).mean().item())\\\\n\\\\n    if args.normalize:\\\\n        log.info(\\\\\\\"Applying L2 normalization\\\\\\\")\\\\n        X = torch.nn.functional.normalize(X, dim=-1)\\\\n\\\\n    input_dim = X.shape[-1]\\\\n    num_classes = 3\\\\n\\\\n    # Try multiple learning rates\\\\n    lrs = [1e-4, 5e-4, 1e-3, 3e-3]\\\\n    best_result = None\\\\n\\\\n    for lr in lrs:\\\\n  